Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // Delete existing data first for a clean seed
    const { error: deleteError } = await supabase
      .from("countries")
      .delete()
      .neq("id", ""); // Delete all rows

    if (deleteError) {
      console.error("Error clearing existing countries:", deleteError);
    }

    // Insert all countries
    const { data, error } = await supabase
      .from("countries")
      .insert(countriesSeed)
      .select();

    if (error) {
      console.error("Error seeding countries:", error);
      throw error;
    }

    console.log(`Successfully seeded ${data?.length} countries`);

    return new Response(
      JSON.stringify({ 
        message: `Successfully seeded ${data?.length} countries`,
        count: data?.length,
        countries: data?.map(c => c.name)
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : 'Unknown error';
    console.error("Error:", err);
    return new Response(
      JSON.stringify({ error: errorMessage }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});
